import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    valid = rem >= 0
    if len(bins) == 0:
        return np.array([], dtype=float)
    max_cap = np.max(bins)
    is_empty = (bins == max_cap)
    scores = np.where(valid, -(rem ** 3) + np.where(is_empty, 10.0, 0.0), -1.0)
    return scores
```

